      "output": "(()=>{\nconst S=F.SHEET,B=F.BEAT,L=F.LENGTH,N={F1:43.654,Ab1:51.913,C2:65.406};\nconst K=[['last hit','last'],['type tick','tick'],['riser','riser'],['hit','hit'],['closed hat','hat'],['clap','clap'],['kick','kick'],['sub bass','sub']];\nconst cues=S.cues.map(c=>({t:c.t,what:c.what}));\nconst ev=c=>{const w=c.what,o=[];for(const[k,v]of K){if(!w.includes(k))continue;if(v=='hit'&&o.some(e=>e.kind=='last'))continue;const e={t:c.t,kind:v,what:w};if(v=='sub'){const m=w.match(/note (\\w+)/);e.f=N[m&&m[1]]||N.F1;e.d=2*B}if(v=='riser')e.d=2*B;if(v=='hat')e.off=/off-beat/.test(w)?1:0;o.push(e)}return o};\nconst events=s=>{s=s==null?L:s;return S.cues.flatMap(ev).filter(e=>e.t>=0&&e.t<s).map(e=>{if(e.d!=null)e.d=Math.min(e.d,s-e.t);if(e.kind=='last')e.d=Math.max(0.05,Math.min(4*B,s-e.t-0.02));return e}).sort((a,b)=>a.t-b.t)};\nconst render=({seconds,sampleRate})=>{\nconst sr=sampleRate||48000,s=seconds==null?L:seconds,ac=new OfflineAudioContext(2,Math.max(1,Math.round(s*sr)),sr),D=ac.destination;\nconst r=F.rand(2026),nb=ac.createBuffer(1,sr*2,sr),nd=nb.getChannelData(0);for(let i=0;i<nd.length;i++)nd[i]=r()*2-1;\nconst M=ac.createGain(),C=ac.createDynamicsCompressor();\nC.threshold.value=-6;C.knee.value=0;C.ratio.value=20;C.attack.value=0.002;C.release.value=0.12;\nM.gain.setValueAtTime(0.4,0);M.gain.setValueAtTime(0.4,Math.max(0,s-0.3));M.gain.linearRampToValueAtTime(0,s);\nM.connect(C);C.connect(D);\nconst il=Math.round(sr*0.9),ir=ac.createBuffer(2,il,sr);for(let c=0;c<2;c++){const d=ir.getChannelData(c);for(let i=0;i<il;i++)d[i]=(r()*2-1)*Math.pow(1-i/il,3)}\nconst cv=ac.createConvolver();cv.buffer=ir;const R=ac.createGain();R.gain.value=0.22;R.connect(cv);cv.connect(M);\nconst out=(lv,rv,pan)=>{const g=ac.createGain(),p=ac.createStereoPanner();p.pan.value=pan||0;g.gain.value=0;g.connect(p);p.connect(M);if(rv){const x=ac.createGain();x.gain.value=rv;p.connect(x);x.connect(R)}return g};\nconst env=(g,t,a,pk,d)=>{const v=g.gain;v.setValueAtTime(0,t);v.linearRampToValueAtTime(pk,t+a);v.exponentialRampToValueAtTime(1e-4,t+a+d);v.setValueAtTime(0,t+a+d+0.002)};\nlet k=0;const noise=(t,d,lp)=>{const n=ac.createBufferSource();n.buffer=nb;n.loop=!!lp;n.start(t,(k++*0.137)%1.5,lp?undefined:d+0.01);if(lp)n.stop(t+d+0.05);return n};\nconst fl=(ty,f,q)=>{const b=ac.createBiquadFilter();b.type=ty;b.frequency.value=f;b.Q.value=q||0.7;return b};\nconst osc=(ty,t,d)=>{const o=ac.createOscillator();o.type=ty;o.start(t);o.stop(t+d+0.05);return o};\nconst sh=ac.createWaveShaper(),cu=new Float32Array(1024);for(let i=0;i<1024;i++){const x=i/511.5-1;cu[i]=Math.tanh(2*x)/Math.tanh(2)}sh.curve=cu;\nconst SB=ac.createGain();SB.gain.value=1;SB.connect(sh);const SO=out(0.71);SO.gain.value=0.71;sh.connect(SO);\nconst P={\nkick:e=>{const o=osc('sine',e.t,0.3),g=out(1);o.frequency.setValueAtTime(150,e.t);o.frequency.exponentialRampToValueAtTime(45,e.t+0.12);o.connect(g);env(g,e.t,0.002,1,0.25)},\nclap:e=>{const f=fl('bandpass',1200,1.4),g=out(1,0.5);f.connect(g);noise(e.t,0.25).connect(f);const v=g.gain;v.setValueAtTime(0,e.t);[0,0.011,0.022].forEach(o=>{v.setValueAtTime(0.63,e.t+o);v.exponentialRampToValueAtTime(0.08,e.t+o+0.009)});v.setValueAtTime(0.5,e.t+0.031);v.exponentialRampToValueAtTime(1e-4,e.t+0.2);v.setValueAtTime(0,e.t+0.21)},\nhat:e=>{const f=fl('highpass',8000),g=out(1,0,e.off?0.25:-0.15);f.connect(g);noise(e.t,0.05).connect(f);env(g,e.t,0.001,e.off?0.25:0.22,0.04)},\nsub:e=>{const o=osc('sine',e.t,e.d),g=ac.createGain();o.frequency.value=e.f;o.connect(g);g.connect(SB);const v=g.gain;v.setValueAtTime(0,e.t);v.linearRampToValueAtTime(0.75,e.t+0.01);v.setValueAtTime(0.75,e.t+e.d-0.04);v.linearRampToValueAtTime(0,e.t+e.d-0.005)},\nriser:e=>{const f=fl('bandpass',400,2.5),g=out(1,0.6);f.connect(g);noise(e.t,e.d,1).connect(f);f.frequency.setValueAtTime(400,e.t);f.frequency.exponentialRampToValueAtTime(6000,e.t+e.d);const v=g.gain;v.setValueAtTime(1e-4,e.t);v.exponentialRampToValueAtTime(0.4*2.2,e.t+e.d-0.01);v.linearRampToValueAtTime(0,e.t+e.d)},\nhit:(e,d)=>{d=d||0.6;const o=osc('sine',e.t,d),g=out(1,0.4);o.frequency.setValueAtTime(180,e.t);o.frequency.exponentialRampToValueAtTime(70,e.t+0.25);o.connect(g);env(g,e.t,0.002,0.9,d);\nconst f=fl('highpass',3000),h=out(1,0.8);f.connect(h);noise(e.t,d,1).connect(f);env(h,e.t,0.002,0.55,d)},\ntick:e=>{const o=osc('square',e.t,0.02),f=fl('bandpass',2000,3),g=out(1,0.3,0.1);o.frequency.value=2000;o.connect(f);f.connect(g);env(g,e.t,0.0005,0.32*1.6,0.015)},\nlast:e=>{P.hit(e,e.d);const o=osc('sine',e.t,e.d),g=ac.createGain();o.frequency.value=N.F1;o.connect(g);g.connect(SB);const v=g.gain;v.setValueAtTime(0,e.t);v.linearRampToValueAtTime(0.85,e.t+0.01);v.exponentialRampToValueAtTime(1e-4,e.t+e.d);v.setValueAtTime(0,e.t+e.d+0.002)}};\nevents(s).forEach(e=>P[e.kind](e));\nreturn ac.startRendering()};\nF.sound={render,cues,events};\nF.test('sound cues follow the sheet',()=>{const E=events(L),bad=S.cues.filter(c=>!E.some(e=>e.t===c.t&&e.what===c.what));const o=E.filter(e=>e.t<0||e.t+(e.d||0)>L);return{ok:!bad.length&&!o.length&&cues.length==S.cues.length,detail:E.length+' events, '+bad.length+' missing, '+o.length+' outside'}});\n})();\n",
